#include <iostream>
#include <array>
#include <string>
#include <sstream>
#include <algorithm>

using namespace std;

long long igra(array<long long, 14> start, int i) {
    long long n = start[i];
    long long addToAll;
    long long result = 0;

    start[i] = 0;
    if (n == 0) {
        return 0;
    }

    addToAll = n / 14;
    n = n % 14;

    for (int j = 0; j < 14; j++) {
        start[j] += addToAll;
    }

    int current = i;
    while (n != 0) {
        current = (current + 1) % 14;
        start[current]++;
        n--;
    }

    for (int j = 0; j < 14; j++) {
        if (start[j] % 2 == 0) {
            result += start[j];
        }
    }
    return result;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    array<long long, 14> start;
    array<long long, 14> end;
    long long max_val = 0;
    string line;

    getline(cin, line);
    stringstream ss(line);
    for (int i = 0; i < 14; i++) {
        ss >> start[i];
    }

    for (int i = 0; i < 14; i++) {
        end[i] = igra(start, i);
    }

    for (int i = 0; i < 14; i++) {
        if (max_val < end[i]) {
            max_val = end[i];
        }
    }

    cout << max_val << "\n";

    return 0;
}

